INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17175$nota-0126$m17175$, $m17176$Training and Racing with a Power Meter.pdf$m17176$, $m17177$369$m17177$, $m17178$The lower, smoother lines... represent the riders' theoretical maximal aerobic power output, as calculated from laboratory-determined VO2max and efficiency, whereas the more jagged lines represent their total power output as directly measured using a power meter... For Rider A, the area under the power-meter line represents 80 percent of the total area (i.e., 80 percent of the work was performed aerobically)... this anaerobic energy production is equivalent to 3.36 liters (L) of O2—in other words, Rider A's maximal accumulated O2 deficit (MAOD) can be estimated at 3.36 L.$m17178$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17179$nota-0126$m17179$, $m17180$Training and Racing with a Power Meter.pdf$m17180$, $m17181$370$m17181$, $m17182$for Rider B the area under the maximal aerobic power output line represents only 72 percent of the total area... The remaining 28 percent therefore must have come from anaerobic sources, leading to an estimated MAOD of 5.27 L... Despite the fact that her VO2max is 4 percent lower... Rider B is able to produce 4 percent more power... during a 3 km pursuit because her anaerobic capacity is much larger.$m17182$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17183$nota-0126$m17183$, $m17184$nota-0082$m17184$, $m17185$complementa$m17185$, $m17186$oferece uma segunda via (baseada em VO2max de laboratório) de caracterizar o fenótipo aeróbio/anaeróbio do atleta, complementar ao Mapa Fenotípico via Power Profile (nota-0082, Cap.8)$m17186$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17187$nota-0136$m17187$, $m17188$Training and Racing with a Power Meter.pdf$m17188$, $m17189$389$m17189$, $m17190$it is not uncommon for track cyclists to perform standing-start efforts in a gear that is larger than normally used when racing, under the assumption that this creates a greater overload on the neuromuscular system... this is not the case. Instead, within fairly broad limits, the gear that is used when performing a standing start has no impact on the force applied to the cranks at any particular cadence. This is because during maximal efforts it is primarily the contractile properties of the cyclist's muscles... that determine the force-velocity relationship when pedaling.$m17190$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17191$nota-0136$m17191$, $m17192$Training and Racing with a Power Meter.pdf$m17192$, $m17193$390$m17193$, $m17194$varying the gear ratio has no effect on the force that a rider's muscles can produce at a particular speed. It only determines how quickly the rider will 'hop, skip, and jump' down his or her maximal force-velocity line.$m17194$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17195$nota-0153$m17195$, $m17196$Manual treinamento.pdf$m17196$, $m17197$29$m17197$, $m17198$Durante esforços leves predominam unidades motoras pequenas, compostas principalmente por fibras do tipo I. À medida que a intensidade aumenta, unidades maiores, contendo fibras do tipo II, passam a ser recrutadas. Esse princípio, conhecido como Princípio do Tamanho de Henneman, representa um dos conceitos fundamentais da fisiologia neuromuscular.$m17198$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17199$nota-0154$m17199$, $m17200$Manual treinamento.pdf$m17200$, $m17201$37$m17201$, $m17202$Sistema Fosfagênio (ATP-PCr) ... Predomina durante esforços máximos com duração aproximada de até dez segundos ... Sistema Glicolítico ... Predomina em esforços intensos com duração entre aproximadamente 30 segundos e alguns minutos ... Sistema Oxidativo ... apresenta menor velocidade de produção de ATP, porém enorme capacidade de sustentação.$m17202$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17203$nota-0154$m17203$, $m17204$nota-0153$m17204$, $m17205$complementa$m17205$, $m17206$junto com o princípio de Henneman, explica a base fisiológica de por que diferentes intensidades/durações de esforço recrutam vias energéticas e fibras musculares distintas$m17206$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17207$nota-0157$m17207$, $m17208$Manual treinamento.pdf$m17208$, $m17209$51$m17209$, $m17210$Débito Cardíaco = Frequência Cardíaca × Volume Sistólico ... Em ciclistas de elite, valores próximos de 40 litros por minuto podem ser observados durante testes máximos.$m17210$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17211$nota-0157$m17211$, $m17212$Manual treinamento.pdf$m17212$, $m17213$50$m17213$, $m17214$Em repouso, adultos não treinados costumam apresentar valores entre 60 e 80 bpm. Em ciclistas altamente treinados, valores inferiores a 40 bpm são relativamente comuns.$m17214$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17215$nota-0157$m17215$, $m17216$Manual treinamento.pdf$m17216$, $m17217$51$m17217$, $m17218$Em indivíduos sedentários, o volume sistólico costuma variar entre 60 e 90 mL por batimento. Em atletas altamente treinados, valores superiores a 150 mL são frequentemente observados.$m17218$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17219$nota-0159$m17219$, $m17220$Manual treinamento.pdf$m17220$, $m17221$59$m17221$, $m17222$Ventilação (VE) = Volume Corrente × Frequência Respiratória... Durante exercícios leves, o aumento da ventilação ocorre principalmente pelo aumento do volume corrente. Em intensidades elevadas... novos aumentos da ventilação dependem principalmente da elevação da frequência respiratória.$m17222$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17223$nota-0159$m17223$, $m17224$Manual treinamento.pdf$m17224$, $m17225$56$m17225$, $m17226$um atleta pode aumentar sua ventilação pulmonar de aproximadamente 8 litros por minuto em repouso para mais de 180 litros por minuto. Em ciclistas profissionais, valores superiores a 220 litros por minuto já foram descritos na literatura.$m17226$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17227$nota-0161$m17227$, $m17228$Manual treinamento.pdf$m17228$, $m17229$65$m17229$, $m17230$VO₂ representa o volume de oxigênio consumido pelo organismo em determinado intervalo de tempo. Pode ser expresso de duas formas: Valor absoluto — Litros por minuto (L·min⁻¹)... Valor relativo — Mililitros por quilograma por minuto (mL·kg⁻¹·min⁻¹)... O valor relativo facilita comparações entre indivíduos com diferentes massas corporais.$m17230$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17231$nota-0162$m17231$, $m17232$Manual treinamento.pdf$m17232$, $m17233$66$m17233$, $m17234$VO₂ = Débito Cardíaco × Diferença Arteriovenosa de Oxigênio... Componente central: capacidade de transportar oxigênio (débito cardíaco, volume sistólico, hemoglobina)... Componente periférico: capacidade do músculo de extrair e utilizar o oxigênio disponível (capilarização, densidade mitocondrial, atividade enzimática, mioglobina).$m17234$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17235$nota-0162$m17235$, $m17236$nota-0157$m17236$, $m17237$pre-requisito$m17237$, $m17238$usa o débito cardíaco (FC × Volume Sistólico) como o principal componente central da equação de Fick$m17238$)
